#!/usr/bin/env python3
"""Round 53 (26 September): earthworm records from GBIF. Upload to the culprits repo's patches folder. Safe to run twice."""
import base64, subprocess, sys, os, tempfile
DIFF = base64.b64decode("")
NOTE = """
## Round 53 (26 September)

- soil_earthworms (Soil biodiversity): GBIF occurrence density tiles, live,
  order Crassiclitellata (backbone key 5958860; Lumbricidae 6103 sits in it),
  choices "Each record" (classic.point) and "Records per hexagon" (hex, 30 per
  tile). Chosen because sWorm / Phillips 2019 state no licence.
- culprits-tiles-more round 53: scripts/atlas_pages_probe.py (by hand) saves
  every hotspot PDF's pages 2+ as text/pictures/rectangles JSON and pages 8-12
  as 1200 px pictures to probe/atlas_pages/, to write the placement of the
  Atlas's detailed city inset maps (owner, 26 September: pages 8-12 hold more
  detailed maps to integrate). Global Safety Net rankings: not wanted (owner).
- Needs rounds 50 and 52 first.
"""
def git(*a):
    return subprocess.run(["git", *a], capture_output=True, text=True)
if not os.path.exists("map/app.js"):
    sys.exit("Run this from the culprits folder.")
with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
    f.write(DIFF); path = f.name
if git("apply", "--check", "-R", path).returncode == 0:
    print("Already applied. Nothing changed.")
else:
    r = git("apply", "--3way", path)
    if r.returncode != 0:
        print(r.stdout + r.stderr)
        git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html")
        sys.exit("Did not apply; nothing changed.")
    print("Code changes applied.")
os.unlink(path)
if os.path.exists("HANDOFF.md"):
    h = open("HANDOFF.md", encoding="utf-8").read()
    if "## Round 53 (26 September)" not in h:
        i = h.index("---") + 3
        open("HANDOFF.md", "w", encoding="utf-8").write(h[:i] + "\n" + NOTE + h[i:])
        print("HANDOFF.md note added.")
